class ConnectionUtility : Form {
 readonly string root=AppDomain.CurrentDomain.BaseDirectory;
 readonly JavaScriptSerializer json=new JavaScriptSerializer();
 readonly Dictionary<string,TextBox> fields=new Dictionary<string,TextBox>();
 readonly TextBox output=new TextBox();
 readonly CheckBox dsnOnly=new CheckBox();
 Process agent; bool busy=false;
 string StateDir {get{return Path.Combine(root,"utility-state");}}
 string Profile {get{return Path.Combine(StateDir,"profile.dpapi");}}
 static byte[] Protect(byte[] bytes){return ProtectedData.Protect(bytes,null,DataProtectionScope.CurrentUser);}
 static byte[] Reveal(byte[] bytes){return ProtectedData.Unprotect(bytes,null,DataProtectionScope.CurrentUser);}
 void SecureState(){Directory.CreateDirectory(StateDir);var acl=new DirectorySecurity();acl.SetAccessRuleProtection(true,false);acl.AddAccessRule(new FileSystemAccessRule(WindowsIdentity.GetCurrent().User,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(WellKnownSidType.LocalSystemSid,null),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(StateDir,acl);}
 string Value(string name){return fields[name].Text.Trim();}
 void Log(string text){if(IsDisposed)return;if(InvokeRequired){BeginInvoke(new MethodInvoker(delegate{Log(text);}));return;}output.AppendText(DateTime.Now.ToString("HH:mm:ss")+" "+text+Environment.NewLine);}
 void Field(Control panel,string key,string label,string value,int y,bool secret){var l=new Label{Text=label,Left=15,Top=y+4,Width=165};var t=new TextBox{Text=value,Left=185,Top=y,Width=485,UseSystemPasswordChar=secret};panel.Controls.Add(l);panel.Controls.Add(t);fields[key]=t;}
 Button Action(Control panel,string text,int x,int y,Action action){var b=new Button{Text=text,Left=x,Top=y,Width=155,Height=30};b.Click+=delegate{try{action();}catch{Log("Action failed. Check the profile, permissions and prerequisites. Credentials were not logged.");}};panel.Controls.Add(b);return b;}
 public ConnectionUtility(){
 Text="PixelPoint Connection & Sync Utility 2.1.1 RC1 (32-bit ODBC)";Width=740;Height=740;StartPosition=FormStartPosition.CenterScreen;
 var tabs=new TabControl{Left=8,Top=8,Width=705,Height=450};var db=new TabPage("Database connection");var sync=new TabPage("Cloud connector");tabs.TabPages.Add(db);tabs.TabPages.Add(sync);Controls.Add(tabs);
 Field(db,"dsn","32-bit System DSN","PixelSqlbase",20,false);Field(db,"host","Database host","127.0.0.1",60,false);Field(db,"port","Database port","2638",100,false);Field(db,"server","Server name","PixelSqlbase",140,false);Field(db,"database","Database name","PixelSqlbase",180,false);Field(db,"user","Reporting username","reportuser",220,false);Field(db,"password","Database password","",260,true);
 dsnOnly.Text="Use DSN settings only (recommended)";dsnOnly.Left=185;dsnOnly.Top=285;dsnOnly.Width=450;dsnOnly.Checked=true;db.Controls.Add(dsnOnly);dsnOnly.CheckedChanged+=delegate{ApplyMode();};ApplyMode();
 Action(db,"Test connection",15,310,Test);Action(db,"Export schema",180,310,ExportSchema);Action(db,"Save protected profile",345,310,Save);Action(db,"Load profile",510,310,LoadProfile);
 db.Controls.Add(new Label{Left=15,Top=355,Width=650,Height=45,Text="Uses the installed 32-bit ODBC driver. Tests run SELECT 1 only. This utility does not start, repair or write to the PixelPoint database. Passwords are protected for this Windows account."});
 Field(sync,"api","Reporting API URL","https://reports.example.com",20,false);Field(sync,"restaurant","Restaurant ID","local-pixelpoint",60,false);Field(sync,"key","Connector API key","",100,true);Field(sync,"zone","IANA timezone","Asia/Bahrain",140,false);Field(sync,"interval","Interval seconds","300",180,false);Field(sync,"days","Lookback days","8",220,false);Field(sync,"node","Node.js 24 path",Path.Combine(Environment.GetEnvironmentVariable("ProgramW6432")??"C:\\Program Files","nodejs\\node.exe"),260,false);
 Action(sync,"Run one sync",15,310,delegate{Start(true);});Action(sync,"Start scheduled sync",180,310,delegate{Start(false);});Action(sync,"Stop connector",345,310,Stop);Action(sync,"Queue diagnostics",510,310,Diagnostics);
 sync.Controls.Add(new Label{Left=15,Top=355,Width=650,Height=45,Text="Set a real HTTPS endpoint and restaurant key. Loopback HTTP is allowed for local testing only. One active connector per store. Profiles and queued sales stay on this computer."});
 output.Left=12;output.Top=470;output.Width=700;output.Height=200;output.Multiline=true;output.ReadOnly=true;output.ScrollBars=ScrollBars.Vertical;Controls.Add(output);
 FormClosing+=delegate(object sender,FormClosingEventArgs args){if(agent!=null&&!agent.HasExited){if(MessageBox.Show("Stop this utility's connector and close?","Connector running",MessageBoxButtons.YesNo)!=DialogResult.Yes){args.Cancel=true;return;}Stop();}};
 if(File.Exists(Profile))LoadProfile();Log("Ready. Enter or load your reporting connection, then test it.");
 }
 void ApplyMode(){foreach(var name in new string[]{"host","port","server","database"})fields[name].Enabled=!dsnOnly.Checked;}
 string ConnectionString(){if(string.IsNullOrWhiteSpace(Value("dsn")))throw new Exception();var b=new OdbcConnectionStringBuilder();b["DSN"]=Value("dsn");b["UID"]=Value("user");b["PWD"]=fields["password"].Text;if(dsnOnly.Checked)return b.ConnectionString;int port;if(!int.TryParse(Value("port"),out port)||port<1||port>65535)throw new Exception();if(Value("host").IndexOfAny(new char[]{';','(',')','{','}'})>=0)throw new Exception();b["ASTART"]="NO";b["LINKS"]="TCPIP(HOST="+Value("host")+";PORT="+port+")";b["ServerName"]=Value("server");b["DBN"]=Value("database");b["CharSet"]="IBM850";return b.ConnectionString;}
 void Background(Action action){if(busy){Log("A database action is already running.");return;}busy=true;ThreadPool.QueueUserWorkItem(delegate{try{action();}catch(OdbcException e){string state=e.Errors.Count>0?e.Errors[0].SQLState:"unknown";Log("Database action failed (SQLSTATE "+state+"). Check server availability, port, names, credentials and driver bitness.");}catch{Log("Action failed; no credential details were logged.");}finally{busy=false;}});}
 void Test(){var connection=ConnectionString();Log("Testing database connection...");Background(delegate{using(var c=new OdbcConnection(connection)){c.Open();using(var cmd=c.CreateCommand()){cmd.CommandText="SELECT 1";cmd.CommandTimeout=15;if(Convert.ToInt32(cmd.ExecuteScalar())!=1)throw new Exception();}Log("Database connection and SELECT 1 passed. The four sales reports still require a sync/reconciliation.");}});}
 void ExportSchema(){var connection=ConnectionString();var dialog=new SaveFileDialog{Filter="Schema JSON|*.json",FileName="PixelPoint-schema.json"};if(dialog.ShowDialog()!=DialogResult.OK)return;var path=dialog.FileName;Background(delegate{using(var c=new OdbcConnection(connection)){c.Open();var data=new Dictionary<string,object>();foreach(var name in new string[]{"Tables","Columns"}){var rows=new List<Dictionary<string,object>>();var table=c.GetSchema(name);foreach(DataRow row in table.Rows){var item=new Dictionary<string,object>();foreach(DataColumn col in table.Columns)item[col.ColumnName]=row[col]==DBNull.Value?null:row[col];rows.Add(item);}data[name]=rows;}File.WriteAllText(path,json.Serialize(data),Encoding.UTF8);Log("Schema metadata exported. No sales rows or passwords were selected.");}});}
 void Save(){SecureState();var data=new Dictionary<string,string>();foreach(var pair in fields)data[pair.Key]=pair.Value.Text;data["dsn_only"]=dsnOnly.Checked.ToString();var bytes=Protect(Encoding.UTF8.GetBytes(json.Serialize(data)));var temp=Profile+".tmp";File.WriteAllBytes(temp,bytes);if(File.Exists(Profile))File.Replace(temp,Profile,null);else File.Move(temp,Profile);Log("Profile saved with Windows current-user protection.");}
 void LoadProfile(){var values=json.Deserialize<Dictionary<string,string>>(Encoding.UTF8.GetString(Reveal(File.ReadAllBytes(Profile))));foreach(var pair in values)if(fields.ContainsKey(pair.Key))fields[pair.Key].Text=pair.Value;string mode;dsnOnly.Checked=!values.TryGetValue("dsn_only",out mode)||mode!="False";ApplyMode();Log("Protected profile loaded for this Windows account.");}
 string WriteConfig(bool requireKey=true){int seconds,days;Uri uri;if(!int.TryParse(Value("interval"),out seconds)||seconds<30||seconds>86400||!int.TryParse(Value("days"),out days)||days<1||days>366)throw new Exception();if(!Uri.TryCreate(Value("api"),UriKind.Absolute,out uri)||(uri.Scheme!="https"&&!(uri.Scheme=="http"&&(uri.Host=="127.0.0.1"||uri.Host=="localhost"))))throw new Exception();if(string.IsNullOrWhiteSpace(Value("restaurant"))||(requireKey&&fields["key"].Text.Length<24)||!File.Exists(Value("node"))||!File.Exists(Path.Combine(root,"connector","agent.mjs")))throw new Exception();SecureState();var cfg=new Dictionary<string,object>{{"restaurant_id",Value("restaurant")},{"api_url",Value("api")},{"allow_http_local",uri.Scheme=="http"},{"key_env","PIXELPOINT_API_KEY"},{"timezone",Value("zone")},{"mode","interval"},{"interval_seconds",seconds},{"daily_at","02:00"},{"lookback_days",days},{"outbox",Path.Combine(StateDir,"outbox")},{"source_owner","DBA"},{"powershell_path",Path.Combine(Environment.GetEnvironmentVariable("WINDIR"),"SysWOW64\\WindowsPowerShell\\v1.0\\powershell.exe")}};var path=Path.Combine(StateDir,"connector.json");File.WriteAllText(path,json.Serialize(cfg),Encoding.UTF8);return path;}
 void Start(bool once){if(agent!=null&&!agent.HasExited){Log("This utility already has a running connector.");return;}var cfg=WriteConfig();var info=new ProcessStartInfo(Value("node"),"connector/agent.mjs"+(once?" --once":"")){WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};info.EnvironmentVariables["CONNECTOR_CONFIG"]=cfg;info.EnvironmentVariables["PIXELPOINT_ODBC"]=ConnectionString();info.EnvironmentVariables["PIXELPOINT_API_KEY"]=fields["key"].Text;agent=new Process{StartInfo=info,EnableRaisingEvents=true};agent.OutputDataReceived+=delegate(object s,DataReceivedEventArgs e){if(e.Data!=null){if(e.Data.Contains("Sync completed"))Log("Synchronization completed.");else if(e.Data.StartsWith("Snapshot acknowledged"))Log("A reporting-day snapshot was acknowledged.");}};agent.ErrorDataReceived+=delegate(object s,DataReceivedEventArgs e){if(e.Data!=null)Log("Connector reported an error. Check database/API connectivity and Queue diagnostics. Queued data is retained.");};var owned=agent;agent.Exited+=delegate{Log("Connector stopped. Exit code: "+owned.ExitCode);};agent.Start();agent.BeginOutputReadLine();agent.BeginErrorReadLine();Log(once?"One synchronization started.":"Scheduled synchronization started. Keep this utility running.");}
 void Stop(){if(agent==null||agent.HasExited){Log("No connector started by this utility is running.");return;}var info=new ProcessStartInfo("taskkill.exe","/PID "+agent.Id+" /T /F"){UseShellExecute=false,CreateNoWindow=true};bool stopped=false;using(var p=Process.Start(info)){if(p.WaitForExit(10000)&&p.ExitCode==0)stopped=agent.WaitForExit(5000);}if(stopped){var lockPath=Path.Combine(StateDir,"outbox","agent.lock");if(File.Exists(lockPath)&&File.ReadAllText(lockPath).Trim()==agent.Id.ToString())File.Delete(lockPath);Log("This utility's connector stopped. Its own PID lock was cleared when identifiable; queued snapshots were retained.");}else Log("Stop could not be confirmed. Check the process before restarting; no lock was cleared.");}
 void Diagnostics(){var cfg=WriteConfig(false);var info=new ProcessStartInfo(Value("node"),"connector/diagnostics.mjs \""+cfg+"\""){WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};Background(delegate{using(var p=Process.Start(info)){var text=p.StandardOutput.ReadToEnd();p.WaitForExit();Log(text);}});}
 [STAThread]static int Main(string[] args){try{if(args.Length==2&&args[0]=="--test-env"){try{using(var c=new OdbcConnection(Environment.GetEnvironmentVariable("PIXELPOINT_ODBC"))){c.Open();using(var cmd=c.CreateCommand()){cmd.CommandText="SELECT 1";cmd.CommandTimeout=15;if(Convert.ToInt32(cmd.ExecuteScalar())!=1)throw new Exception();}}File.WriteAllText(args[1],"{\"passed\":true,\"bitness\":32,\"check\":\"native utility ODBC and SELECT 1\"}");return 0;}catch(OdbcException e){var state=e.Errors.Count>0?e.Errors[0].SQLState:"unknown";File.WriteAllText(args[1],new JavaScriptSerializer().Serialize(new Dictionary<string,object>{{"passed",false},{"sqlstate",state}}));return 2;}}if(args.Length==2&&args[0]=="--self-test"){var sample=Encoding.UTF8.GetBytes("synthetic-profile");if(Encoding.UTF8.GetString(Reveal(Protect(sample)))!="synthetic-profile")return 1;using(var form=new ConnectionUtility()){if(form.fields.Count!=14)return 2;form.fields["password"].Text="synthetic-only-test";form.dsnOnly.Checked=true;var connection=new OdbcConnectionStringBuilder(form.ConnectionString());if(connection.Count!=3||connection.ContainsKey("LINKS")||connection.ContainsKey("DBN"))return 3;form.dsnOnly.Checked=false;connection=new OdbcConnectionStringBuilder(form.ConnectionString());if(!connection.ContainsKey("LINKS"))return 4;File.WriteAllText(args[1],"{\"passed\":true,\"bitness\":"+(IntPtr.Size*8)+",\"checks\":[\"DPAPI roundtrip\",\"WinForms controls constructed\"]}");}return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new ConnectionUtility());return 0;}catch{if(args.Length==0)MessageBox.Show("The utility could not start. Check the installed .NET runtime and folder permissions.");return 1;}}
}





